  perform tell(p_world, p_uid, 'Stored: ' || v_fit || ' × ' || lower(item_name(it)) || ' in ' || c.name || '''s panniers.'
    || case when v_want > v_fit then ' ' || (v_want - v_fit) || ' did not fit.' else '' end, 'event');
end $function$
